'use strict';

function detachRecords(records) {
  if (!Array.isArray(records)) throw new TypeError('records must be an array');
  const seen = new Set();
  return records.map(record => {
    if (!isPlain(record) || typeof record.key !== 'string' || record.key.trim() === '' || !isPlain(record.metadata)) throw new TypeError('invalid record');
    const key = record.key.trim();
    if (seen.has(key)) throw new RangeError('duplicate key');
    seen.add(key);
    for (const value of Object.values(record.metadata)) {
      if (!['string', 'number', 'boolean'].includes(typeof value) || (typeof value === 'number' && !Number.isFinite(value))) throw new TypeError('invalid metadata');
    }
    return { key, metadata: record.metadata };
  });
}
function isPlain(value) {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

module.exports = { detachRecords };
```

