'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['detachRecords']);
const { detachRecords } = api;

const empty = [];
const emptyResult = detachRecords(empty);
assert.deepStrictEqual(emptyResult, []);
assert.notStrictEqual(emptyResult, empty);

const metadata = Object.create(null);
metadata.count = 2;
metadata.active = true;
metadata.note = 'ok';
const records = [
  { key: ' alpha ', metadata },
  { key: 'beta', metadata: {} }
];
const result = detachRecords(records);
assert.deepStrictEqual(result, [
  { key: 'alpha', metadata: { count: 2, active: true, note: 'ok' } },
  { key: 'beta', metadata: {} }
]);
assert.notStrictEqual(result, records);
assert.notStrictEqual(result[0], records[0]);
assert.notStrictEqual(result[0].metadata, records[0].metadata);
result[0].key = 'changed';
result[0].metadata.count = 99;
result.push({ key: 'extra', metadata: {} });
assert.strictEqual(records[0].key, ' alpha ');
assert.strictEqual(records[0].metadata.count, 2);
assert.strictEqual(records.length, 2);
metadata.note = 'input changed';
assert.strictEqual(result[0].metadata.note, 'ok');

for (const bad of [null, {}, 'records']) {
  assert.throws(() => detachRecords(bad), TypeError);
}
for (const record of [
  null,
  [],
  { key: '', metadata: {} },
  { key: 1, metadata: {} },
  { key: 'x', metadata: [] },
  { key: 'x', metadata: { bad: null } },
  { key: 'x', metadata: { bad: undefined } },
  { key: 'x', metadata: { bad: Infinity } },
  { key: 'x', metadata: { bad: {} } }
]) {
  assert.throws(() => detachRecords([record]), TypeError);
}
assert.throws(() => detachRecords([
  { key: 'same', metadata: {} },
  { key: ' same ', metadata: {} }
]), RangeError);

const input = [{ key: 'safe', metadata: { value: 1 } }];
const before = JSON.stringify(input);
assert.throws(() => detachRecords([
  input[0], { key: 'bad', metadata: { value: NaN } }
]), TypeError);
assert.strictEqual(JSON.stringify(input), before);

